const claimOutbox = `-- name: ClaimOutbox :many
WITH due AS (
    SELECT id FROM outbox_messages
    WHERE delivered_at IS NULL AND available_at <= now()
    -- Priority first, then age: a receipt must not wait for a newsletter.
    ORDER BY priority, available_at
    LIMIT $2::integer
    FOR UPDATE SKIP LOCKED
)
UPDATE outbox_messages m
SET attempts = m.attempts + 1,
    available_at = now() + $1::interval
FROM due
WHERE m.id = due.id
RETURNING m.id, m.topic, m.payload, m.attempts
`

type ClaimOutboxParams struct {
	Lease     pgtype.Interval
	BatchSize int32
}

type ClaimOutboxRow struct {
	ID       uuid.UUID
	Topic    string
	Payload  []byte
	Attempts int32
}

// Claim a batch of due messages, taking a LEASE on each. FOR UPDATE SKIP LOCKED
// is not enough — that lock lives only for THIS statement — so pushing
// available_at forward is what makes the claim exclusive.
// attempts rises on the CLAIM, or it counts nothing about failures.
func (q *Queries) ClaimOutbox(ctx context.Context, arg ClaimOutboxParams) ([]ClaimOutboxRow, error) {
	rows, err := q.db.Query(ctx, claimOutbox, arg.Lease, arg.BatchSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ClaimOutboxRow{}
	for rows.Next() {
		var i ClaimOutboxRow
		if err := rows.Scan(
			&i.ID,
			&i.Topic,
			&i.Payload,
			&i.Attempts,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

