const createCategory = `-- name: CreateCategory :execrows
INSERT INTO categories (slug, name, name_en, icon_key, parent_id, position)
SELECT $1::text, $2::text, nullif($3::text, ''),
       nullif($4::text, ''), parent.id,
       coalesce((SELECT max(c.position) + 1 FROM categories c
                 WHERE c.parent_id IS NOT DISTINCT FROM parent.id), 0)
FROM (
    SELECT c.id FROM categories c WHERE c.slug = $5::text
    UNION ALL
    SELECT NULL::uuid WHERE $5::text = ''
) parent
`

type CreateCategoryParams struct {
	Slug       string
	Name       string
	NameEn     string
	IconKey    string
	ParentSlug string
}

// The parent is a derived table and not a scalar subquery: that would yield NULL
// for a slug that does not exist, creating a ROOT category and reporting
// success. No rows is how the caller learns the parent was not found.
func (q *Queries) CreateCategory(ctx context.Context, arg CreateCategoryParams) (int64, error) {
	result, err := q.db.Exec(ctx, createCategory,
		arg.Slug,
		arg.Name,
		arg.NameEn,
		arg.IconKey,
		arg.ParentSlug,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

