const memberStanding = `-- name: MemberStanding :one
SELECT
    member_spend($1, $2::integer, NULL)::bigint AS spend_cents,
    coalesce((SELECT localized_name(t.name, t.name_en, $3::text)
              FROM membership_tiers t
              WHERE t.id = member_tier($1, $2::integer, NULL)), '')::text
        AS tier_name,
    coalesce((SELECT t.points_multiplier_bp FROM membership_tiers t
              WHERE t.id = member_tier($1, $2::integer, NULL)), 10000)::integer
        AS multiplier_bp,
    coalesce((SELECT localized_name(n.name, n.name_en, $3::text)
              FROM membership_tiers n
              WHERE n.min_spend_cents > member_spend($1, $2::integer, NULL)
              ORDER BY n.min_spend_cents LIMIT 1), '')::text AS next_name,
    coalesce((SELECT n.min_spend_cents - member_spend($1, $2::integer, NULL)
              FROM membership_tiers n
              WHERE n.min_spend_cents > member_spend($1, $2::integer, NULL)
              ORDER BY n.min_spend_cents LIMIT 1), 0)::bigint AS next_needs_cents
`

type MemberStandingParams struct {
	UserID     uuid.UUID
	WindowDays int32
	Locale     string
}

type MemberStandingRow struct {
	SpendCents     int64
	TierName       string
	MultiplierBp   int32
	NextName       string
	NextNeedsCents int64
}

// Derived on every read, never stored: a stored tier drifts from the orders
// behind it the moment one is cancelled.
func (q *Queries) MemberStanding(ctx context.Context, arg MemberStandingParams) (MemberStandingRow, error) {
	row := q.db.QueryRow(ctx, memberStanding, arg.UserID, arg.WindowDays, arg.Locale)
	var i MemberStandingRow
	err := row.Scan(
		&i.SpendCents,
		&i.TierName,
		&i.MultiplierBp,
		&i.NextName,
		&i.NextNeedsCents,
	)
	return i, err
}

const mergeCartItems = `-- name: MergeCartItems :exec
INSERT INTO cart_items (cart_id, variant_id, quantity)
SELECT $2, src.variant_id, src.quantity FROM cart_items src WHERE src.cart_id = $1
ON CONFLICT (cart_id, variant_id) DO UPDATE
SET quantity = least(cart_items.quantity + EXCLUDED.quantity, 999)
`

type MergeCartItemsParams struct {
	CartID   uuid.UUID
	CartID_2 uuid.UUID
}

// Quantities add rather than replace, capped at the line ceiling.
func (q *Queries) MergeCartItems(ctx context.Context, arg MergeCartItemsParams) error {
	_, err := q.db.Exec(ctx, mergeCartItems, arg.CartID, arg.CartID_2)
	return err
}

const myWarranties = `-- name: MyWarranties :many
SELECT w.id, w.unit_no, coalesce(w.serial_number, '') AS serial_number,
       w.registered_at, w.expires_on,
       (w.expires_on >= shop_today())::boolean AS in_force,
       ol.product_name, ol.variant_label, o.order_number,
       coalesce(p.slug, '') AS product_slug
FROM warranty_registrations w
JOIN order_lines ol ON ol.id = w.order_line_id
JOIN orders o ON o.id = ol.order_id
LEFT JOIN products p ON p.id = ol.product_id
WHERE w.user_id = $1
ORDER BY w.expires_on DESC, w.id
`

type MyWarrantiesRow struct {
	ID           uuid.UUID
	UnitNo       int16
	SerialNumber string
	RegisteredAt time.Time
	ExpiresOn    time.Time
	InForce      bool
	ProductName  string
	VariantLabel pgtype.Text
	OrderNumber  string
	ProductSlug  string
}

// What this customer has registered.
func (q *Queries) MyWarranties(ctx context.Context, userID uuid.NullUUID) ([]MyWarrantiesRow, error) {
	rows, err := q.db.Query(ctx, myWarranties, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MyWarrantiesRow{}
	for rows.Next() {
		var i MyWarrantiesRow
		if err := rows.Scan(
			&i.ID,
			&i.UnitNo,
			&i.SerialNumber,
			&i.RegisteredAt,
			&i.ExpiresOn,
			&i.InForce,
			&i.ProductName,
			&i.VariantLabel,
			&i.OrderNumber,
			&i.ProductSlug,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

