const productVariants = `-- name: ProductVariants :many
SELECT
    pv.id,
    pv.sku,
    pv.price_cents,
    pv.compare_at_price_cents,
    (pv.stock_quantity > pv.safety_stock) AS sellable,
    (pv.stock_quantity - pv.safety_stock)::integer AS sellable_quantity,
    pv.preorder_release_on,
    coalesce(
        (SELECT array_agg(o.name ORDER BY o.position, o.id)
         FROM variant_option_values vov
         JOIN product_options o ON o.id = vov.option_id
         WHERE vov.variant_id = pv.id),
        ARRAY[]::text[]
    )::text[] AS option_names,
    coalesce(
        (SELECT array_agg(v.value ORDER BY o.position, o.id)
         FROM variant_option_values vov
         JOIN product_options o ON o.id = vov.option_id
         JOIN product_option_values v ON v.id = vov.option_value_id
         WHERE vov.variant_id = pv.id),
        ARRAY[]::text[]
    )::text[] AS option_values
FROM product_variants pv
WHERE pv.product_id = $1 AND pv.is_active
ORDER BY pv.position, pv.id
`

type ProductVariantsRow struct {
	ID                  uuid.UUID
	SKU                 string
	PriceCents          int64
	CompareAtPriceCents pgtype.Int8
	Sellable            bool
	SellableQuantity    int32
	PreorderReleaseOn   pgtype.Date
	OptionNames         []string
	OptionValues        []string
}

// sellable is stock_quantity > safety_stock, the floor record_inventory_movement
// enforces.
func (q *Queries) ProductVariants(ctx context.Context, productID uuid.UUID) ([]ProductVariantsRow, error) {
	rows, err := q.db.Query(ctx, productVariants, productID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProductVariantsRow{}
	for rows.Next() {
		var i ProductVariantsRow
		if err := rows.Scan(
			&i.ID,
			&i.SKU,
			&i.PriceCents,
			&i.CompareAtPriceCents,
			&i.Sellable,
			&i.SellableQuantity,
			&i.PreorderReleaseOn,
			&i.OptionNames,
			&i.OptionValues,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

