const wishlistItems = `-- name: WishlistItems :many
SELECT
    p.slug,
    localized_name(p.name, p.name_en, $2::text) AS name,
    p.summary,
    b.name AS brand,
    mv.price_cents AS min_price_cents,
    -- Whether that price is the cheapest of several, so a card can say "from"
    -- rather than state one variant's price as the product's.
    EXISTS (
        SELECT 1 FROM product_variants dv
        WHERE dv.product_id = p.id AND dv.is_active AND dv.price_cents > mv.price_cents
    ) AS price_varies,
    mv.compare_at_price_cents,
    coalesce(rv.rating, 0)::float8 AS rating,
    coalesce(rv.n, 0)::bigint AS rating_count,
    EXISTS (
        SELECT 1 FROM product_variants sv
        WHERE sv.product_id = p.id AND sv.is_active
          AND sv.stock_quantity > sv.safety_stock
    ) AS in_stock,
    coalesce(img.storage_key, '') AS image_key,
    coalesce(localized_name(img.alt_text, img.alt_text_en, $2::text), '')::text AS image_alt,
    coalesce(img.width, 0)::integer AS image_width,
    coalesce(img.height, 0)::integer AS image_height
FROM wishlist_items w
JOIN products p ON p.id = w.product_id
JOIN brands b ON b.id = p.brand_id
JOIN LATERAL (
    SELECT price_cents, compare_at_price_cents
    FROM product_variants
    WHERE product_id = p.id AND is_active
    ORDER BY (stock_quantity > safety_stock) DESC, price_cents
    LIMIT 1
) mv ON true
LEFT JOIN LATERAL (
    SELECT avg(rating)::float8 AS rating, count(*) AS n
    FROM visible_reviews WHERE product_id = p.id
) rv ON true
LEFT JOIN LATERAL (
    SELECT storage_key, alt_text, alt_text_en, width, height
    FROM product_images WHERE product_id = p.id ORDER BY position LIMIT 1
) img ON true
WHERE w.user_id = $1 AND p.status = 'active'
ORDER BY w.created_at DESC, p.id DESC
`

type WishlistItemsParams struct {
	UserID uuid.UUID
	Locale string
}

type WishlistItemsRow struct {
	Slug                string
	Name                string
	Summary             pgtype.Text
	Brand               string
	MinPriceCents       int64
	PriceVaries         bool
	CompareAtPriceCents pgtype.Int8
	Rating              float64
	RatingCount         int64
	InStock             bool
	ImageKey            string
	ImageAlt            string
	ImageWidth          int32
	ImageHeight         int32
}

// The cheapest sellable variant sets the price, the way the listing reads it.
// status = 'active' as a LITERAL: a parameter cannot use the partial index.
func (q *Queries) WishlistItems(ctx context.Context, arg WishlistItemsParams) ([]WishlistItemsRow, error) {
	rows, err := q.db.Query(ctx, wishlistItems, arg.UserID, arg.Locale)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WishlistItemsRow{}
	for rows.Next() {
		var i WishlistItemsRow
		if err := rows.Scan(
			&i.Slug,
			&i.Name,
			&i.Summary,
			&i.Brand,
			&i.MinPriceCents,
			&i.PriceVaries,
			&i.CompareAtPriceCents,
			&i.Rating,
			&i.RatingCount,
			&i.InStock,
			&i.ImageKey,
			&i.ImageAlt,
			&i.ImageWidth,
			&i.ImageHeight,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const workerHealth = `-- name: WorkerHealth :one
SELECT
    (SELECT count(*) FROM outbox_messages
     WHERE delivered_at IS NULL)::bigint AS outbox_pending,
    (SELECT greatest(coalesce(extract(epoch FROM now() - min(available_at)), 0), 0)
     FROM outbox_messages WHERE delivered_at IS NULL)::bigint AS outbox_oldest_seconds,
    (SELECT count(*) FROM outbox_messages
     WHERE delivered_at IS NULL AND attempts >= $1::integer)::bigint AS outbox_stuck,
    -- The sweeper's own predicate, not merely expired: release_reservation
    -- refuses a committed or fully-funded order's hold, so counting every
    -- expired row reports stock the sweeper is designed never to release, on a
    -- page whose caption says a backlog means goods nobody can buy. It can only
    -- grow, which is alarm fatigue on the page built to make failure visible.
    (SELECT count(*) FROM inventory_reservations ir
     JOIN orders o ON o.id = ir.order_id
     WHERE ir.state = 'held' AND ir.expires_at < now()
       AND NOT order_is_committed(ir.order_id)
       AND (o.fulfillment_status = 'cancelled'
            OR order_amount_owed(ir.order_id) <> 0)
       -- Match ExpiredReservations: reconciliation deliberately pins stock
       -- while provider money may exist, so it is not a sweeper backlog.
       AND (o.fulfillment_status = 'cancelled' OR (
           NOT EXISTS (
               SELECT 1 FROM payments p
               WHERE p.order_id = ir.order_id
                 AND p.status = 'requires_reconciliation'
           )
           AND NOT EXISTS (
               SELECT 1
               FROM payment_webhook_events e
               JOIN payments p
                 ON p.provider = e.provider AND p.provider_ref = e.object_ref
               WHERE p.order_id = ir.order_id
                 AND e.unreconciled IS NOT NULL AND e.reconciled_at IS NULL
           )
       )))::bigint AS expired_holds,
    (SELECT coalesce(extract(epoch FROM now() - max(computed_at)), 0)
     FROM product_copurchases)::bigint AS copurchase_age_seconds,
    EXISTS (SELECT 1 FROM product_copurchases) AS copurchase_ever_built,
    (SELECT count(*) FROM sessions WHERE expires_at <= now())::bigint AS expired_sessions,
    (SELECT count(*) FROM media_objects m
     WHERE NOT EXISTS (SELECT 1 FROM product_images p WHERE p.storage_key = m.digest)
       AND NOT EXISTS (SELECT 1 FROM hero_slides h WHERE h.image_key = m.digest)
       AND m.created_at < now() - interval '24 hours')::bigint AS unreferenced_media,
    -- Events accepted and NOT acted on: a known Stripe object this binary could
    -- not read, paid money with no local payment row, paid money for an order
    -- already cancelled, or a completed checkout whose money is still in
    -- flight. Each is still marked processed because retrying the same event
    -- changes nothing; the durable reason makes the human action countable
    -- instead of leaving only a log line nobody reads.
    ((SELECT count(*) FROM payment_webhook_events
      WHERE unreconciled IS NOT NULL AND reconciled_at IS NULL)
     +
     (SELECT count(*) FROM payments p
      WHERE p.status = 'requires_reconciliation'
        AND NOT EXISTS (
            SELECT 1 FROM payment_webhook_events e
            WHERE e.provider = p.provider AND e.object_ref = p.provider_ref
              AND e.unreconciled IS NOT NULL AND e.reconciled_at IS NULL
        )))::bigint AS unreconciled_payments
`

type WorkerHealthRow struct {
	OutboxPending        int64
	OutboxOldestSeconds  int64
	OutboxStuck          int64
	ExpiredHolds         int64
	CopurchaseAgeSeconds int64
	CopurchaseEverBuilt  bool
	ExpiredSessions      int64
	UnreferencedMedia    int64
	UnreconciledPayments int64
}

// Overdue is measured from available_at — when a message became DUE — because
// the claim lease and the backoff push it forward. copurchase_ever_built is
// separate from the age because max() over an empty table is NULL, which sqlc
// infers as non-nullable and pgx then refuses to scan: a fresh deployment only.
func (q *Queries) WorkerHealth(ctx context.Context, maxAttempts int32) (WorkerHealthRow, error) {
	row := q.db.QueryRow(ctx, workerHealth, maxAttempts)
	var i WorkerHealthRow
	err := row.Scan(
		&i.OutboxPending,
		&i.OutboxOldestSeconds,
		&i.OutboxStuck,
		&i.ExpiredHolds,
		&i.CopurchaseAgeSeconds,
		&i.CopurchaseEverBuilt,
		&i.ExpiredSessions,
		&i.UnreferencedMedia,
		&i.UnreconciledPayments,
	)
	return i, err
}
